func wrapWebLocalizer(lang string, t func(string, ...any) string) func(string, ...any) string {
	normalized := strings.TrimSpace(strings.ToLower(lang))
	if normalized == "" || normalized == "es" {
		return t
	}
	return func(id string, args ...any) string {
		if normalized == "en" {
			if fallback, ok := webLocalEnglishFallback[id]; ok {
				return fallback
			}
		}
		translated := t(id, args...)
		if translated == id {
			if fallback, ok := webLocalEnglishFallback[id]; ok {
				return fallback
			}
		}
		return translated
	}
}
